const servers = [
  { name: "A", healthy: true },
  { name: "B", healthy: false },
  { name: "C", healthy: true }
];
const ready = servers.filter(server => server.healthy);
for (let request = 0; request < 4; request++) {
  const target = ready.length ? ready[request % ready.length].name : "unavailable";
  console.log(`request ${request + 1}: ${target}`);
}
